"""Original CPU cache/provenance regressions using real v2 translator modules.

The shared full-TU fixture links actual SHA/file/pack/lock code, and forbids child
translation/background work. Modules are generated by the supplied real compiler.
Baseline mode retains the old shader TU; the new pure header only authors the
same owned input packets. No GPU, loader, title data, or copied implementation.
"""
import argparse
import copy
import hashlib
import json
from pathlib import Path
import shutil
import struct
import subprocess
import sys
import unittest

import geometry_passthrough_fixture as original
import geometry_shader_cache_test as cache_test

ROOT = Path(__file__).resolve().parents[1]


class PassthroughCache(unittest.TestCase):
    run_fixture = cache_test.GeometryCache.run_fixture
    put_pair = cache_test.GeometryCache.put_pair
    module = cache_test.GeometryCache.module

    @classmethod
    def setUpClass(cls):
        cache_test.args = args
        cache_test.GeometryCache.setUpClass.__func__(cls)
        jobs = []
        for name, locations in (('pass_a', [0]), ('pass_b', [6]), ('pass_position', [])):
            path = cls.modules / (name + '.code')
            path.write_bytes(original.program())
            jobs.append(dict(key=name, stage='gs', code=str(path.resolve()), c1='', debug=False,
                             geometry_version=2, gs_input='triangles', gs_passthrough_skip=original.skip_words(locations)))
        result = subprocess.run([args.translator, '--serve'],
            input=''.join(json.dumps(dict(job=j, out=str(cls.modules.resolve()))) + '\n' for j in jobs),
            capture_output=True, text=True, timeout=60)
        (args.out / 'passthrough-translator.log').write_text(result.stdout + result.stderr)
        if result.returncode or result.stdout.splitlines() != ['ok ' + j['key'] for j in jobs]:
            raise AssertionError(result.stdout + result.stderr)
        for job in jobs:
            subprocess.run([args.spirv_val, '--target-env', 'vulkan1.3', str(cls.modules / (job['key'] + '.spv'))],
                           check=True, capture_output=True, timeout=15)

    def packet(self, name='a', locations=(0,)):
        suffix = hashlib.sha256((self._testMethodName + '/' + name).encode()).hexdigest()[:12]
        directory = args.out / ('p-' + suffix)
        directory.mkdir(exist_ok=True)
        code = bytes(0x30) + original.program()
        control = bytearray(0x880)
        struct.pack_into('<II', control, 0x700, len(code), len(code) + 8)
        struct.pack_into('<I', control, 0x714, 2)
        control[0x7f8:0x800] = b'canaries'
        control[0x840:0x860] = bytes([0x5a]) * 32
        cp, raw, packed = directory / 'code.bin', directory / 'control.bin', directory / 'packed.bin'
        cp.write_bytes(code + bytes.fromhex('123456789abcdef0'))
        raw.write_bytes(control)
        words = original.skip_words(locations)
        result = self.run_fixture('pack-pass', cp.resolve(), raw.resolve(), ','.join(map(hex, words)), packed.resolve())
        self.assertTrue(result['accepted'])
        self.assertEqual((result['status'], result['skip']), (1, words))
        return cp.resolve(), packed.resolve(), raw.resolve()

    def seed(self, name='a', module='pass_a', locations=(0,), record=False):
        code, control, _ = self.packet(name, locations)
        suffix = hashlib.sha256((self._testMethodName + '/' + name).encode()).hexdigest()[:12]
        directory = args.out / ('c-' + suffix)
        result = self.run_fixture('record-pass' if record else 'seed-pass', code, control,
            (self.modules / (module + '.spv')).resolve(), (self.modules / (module + '.res.json')).resolve(), cache=directory)
        self.assertTrue(result['accepted'])
        return directory, result, code, control

    def load(self, directory, manifest, mode='private'):
        return self.run_fixture('load', mode, manifest['key'], manifest['iid'], cache=directory)

    def input_path(self, directory, manifest):
        return directory / 'in' / (manifest['iid'] + '.in')

    def test_canonical_envelope_canaries_and_strict_source_context(self):
        code, packed, raw = self.packet()
        a, b = raw.read_bytes(), packed.read_bytes()
        self.assertEqual(a[:0x800], b[:0x800])
        self.assertEqual(a[0x840:], b[0x840:])
        self.assertEqual(b[0x800:0x808], b'TKGSMETA')
        self.assertEqual(struct.unpack_from('<4I', b, 0x808), (1, 64, 1, 1))
        self.assertEqual(b[0x838:0x840], bytes(8))
        variants = [('version', 0x808, 2), ('size', 0x80c, 96), ('native', 0x810, 2),
                    ('unknown_kind', 0x810, 7), ('gate', 0x814, 0), ('reserved', 0x838, 1),
                    ('partial_position', 0x818, 0x1fffffff), ('partial_location', 0x81c, 0xfffffff1),
                    ('builtin', 0x82c, 0xfffffffe), ('stage', 0x714, 0), ('length', 0x704, 0xffffffff)]
        for name, offset, value in variants:
            with self.subTest(field=name):
                changed = bytearray(b); struct.pack_into('<I', changed, offset, value)
                path, output = args.out / (name + '.control'), args.out / (name + '.out')
                path.write_bytes(changed)
                status = self.run_fixture('pack-pass', code, path.resolve(), ','.join(map(hex, original.skip_words([0]))), output.resolve())
                self.assertFalse(status['accepted'])
                self.assertEqual(status['status'], -1)
                self.assertEqual(output.read_bytes(), changed)
        for name, offset, value in [('raw_max', 0x40, 3), ('invocations', 0x38, 2 << 24),
                                     ('kind', 0x30, 0x01001062), ('native_sph', 0x30, 0x01001081)]:
            changed = bytearray(code.read_bytes()); struct.pack_into('<I', changed, offset, value)
            path = args.out / (name + '.code'); path.write_bytes(changed)
            result = self.run_fixture('get-pass', path.resolve(), packed, ','.join(map(hex, original.skip_words([0]))),
                                      (args.out / (name + '.out')).resolve())
            self.assertEqual(result['status'], -1)

    def test_request_identity_and_stored_input_format(self):
        records = []
        for name, module, locations in [('a', 'pass_a', [0]), ('b', 'pass_b', [6])]:
            directory, manifest, code, control = self.seed(name, module, locations)
            request = self.run_fixture('request', 3, 4, code, control, cache=directory)
            self.assertTrue(request['accepted'])
            job = request['request']['job']
            self.assertEqual((job['geometry_version'], job['gs_input'], job['gs_passthrough_skip']),
                             (2, 'triangles', original.skip_words(locations)))
            self.assertNotIn('c0', job)
            self.assertEqual(job['c1'], '123456789abcdef0')
            data = self.input_path(directory, manifest).read_bytes()
            self.assertEqual(struct.unpack_from('<6I', data)[0:3], (0x49534b54, 2, 3))
            self.assertEqual(struct.unpack_from('<I', data, 20)[0], 148)
            self.assertEqual(data[172:172 + 0x880], control.read_bytes())
            loaded = self.run_fixture('load-input', manifest['iid'], cache=directory)
            self.assertTrue(loaded['recreated'])
            self.assertEqual(loaded['request'], request['request'])
            records.append(manifest)
        for field in ('hash', 'iid', 'key'):
            self.assertNotEqual(records[0][field], records[1][field])

    def test_warm_private_by_iid_and_packed_loads_without_use_files(self):
        for mode in ('private', 'input', 'private-packed', 'input-packed', 'private-memory', 'input-memory'):
            with self.subTest(mode=mode):
                directory, manifest, _, _ = self.seed(mode)
                for path in directory.glob('*.use'):
                    path.unlink()
                if 'packed' in mode:
                    self.packer.pack(directory, keep=True)
                    (directory / (manifest['key'] + '.spv')).unlink()
                    (directory / (manifest['key'] + '.res.json')).unlink()
                    self.input_path(directory, manifest).unlink()
                result = self.load(directory, manifest, mode)
                self.assertTrue(result['accepted'])
                self.assertEqual((result['stage'], result['input'], result['max_vertices']), (3, 4, 3))
                self.assertEqual(result['owned'], int(mode.startswith('private') and 'memory' not in mode))

    def test_private_and_memory_hits_require_matching_source_provenance(self):
        for mode in ('private', 'input', 'private-memory', 'input-memory', 'private-memory-missing', 'input-memory-missing'):
            with self.subTest(mode=mode):
                directory, manifest, _, _ = self.seed(mode)
                if 'missing' not in mode:
                    self.input_path(directory, manifest).unlink()
                self.assertFalse(self.load(directory, manifest, mode)['accepted'])
        for name, relative, value in [('native', 0x810, 2), ('version', 0x808, 2),
                                       ('different_control', 0x7f8, 99), ('source_stage', 0x714, 0)]:
            directory, manifest, _, _ = self.seed(name)
            path = self.input_path(directory, manifest)
            data = bytearray(path.read_bytes()); struct.pack_into('<I', data, 172 + relative, value); path.write_bytes(data)
            for mode in ('private', 'input', 'private-memory', 'input-memory'):
                with self.subTest(corruption=name, mode=mode):
                    self.assertFalse(self.load(directory, manifest, mode)['accepted'])
        directory, manifest, _, _ = self.seed('v1-output')
        self.put_pair(directory, manifest['key'], *self.module('triangles'))
        for mode in ('private', 'input', 'private-memory', 'input-memory'):
            self.assertFalse(self.load(directory, manifest, mode)['accepted'])
        self.put_pair(directory, manifest['key'], *self.module('fragment'))
        for mode in ('private', 'input', 'private-memory', 'input-memory'):
            self.assertFalse(self.load(directory, manifest, mode)['accepted'])

    def test_request_disk_and_memory_candidates_match_raw_masks(self):
        directory, manifest, code, control = self.seed('wrong', 'pass_b', [0])
        for mode in ('request-load', 'request-memory'):
            self.assertFalse(self.run_fixture(mode, 3, 4, code, control, cache=directory)['accepted'])

    def test_translation_fallback_cannot_return_another_input_id(self):
        directory, a, _, _ = self.seed('original')
        code, control, _ = self.packet('replacement', [6])
        b = self.run_fixture('seed-pass', code, control,
            (self.modules / 'pass_b.spv').resolve(), (self.modules / 'pass_b.res.json').resolve(), cache=directory)
        self.assertTrue(b['accepted'])
        self.assertNotEqual(a['iid'], b['iid'])
        valid_a = self.load(directory, a, 'input-translate')
        self.assertTrue(valid_a['accepted'])
        self.assertEqual(valid_a['iid'], a['iid'])
        self.input_path(directory, a).write_bytes(self.input_path(directory, b).read_bytes())
        # Both shaders are real valid compiler outputs. The named stored input
        # now describes B, so A's ordinary cache admission must first reject it.
        self.assertFalse(self.load(directory, a, 'private')['accepted'])
        self.assertFalse(self.load(directory, a, 'input')['accepted'])
        fallback = self.load(directory, a, 'input-translate')
        self.assertFalse(fallback['accepted'], 'requested ' + a['iid'] + ', returned ' + str(fallback))
        valid_b = self.load(directory, b, 'input-translate')
        self.assertTrue(valid_b['accepted'])
        self.assertEqual(valid_b['iid'], b['iid'])

    def test_reflection_masks_types_duplicates_and_execution_modes(self):
        module, good = self.module('pass_a')
        cases = []
        for value in (None, False, 1, 'true'):
            bad = copy.deepcopy(good); bad['geometry']['source_passthrough'] = value; cases.append(('source_' + str(value), bad))
        for words in (original.skip_words([6]), [1] * 7, [1] * 9,
                      [True] + [0xffffffff] * 7, [0.0] + [0xffffffff] * 7,
                      [-1] + [0xffffffff] * 7, [0x100000000] + [0xffffffff] * 7):
            bad = copy.deepcopy(good); bad['gs_passthrough_skip'] = words; cases.append(('mask_' + str(len(cases)), bad))
        for field, value in [('passthrough', True), ('max_output_vertices', 1), ('invocations', 2)]:
            bad = copy.deepcopy(good); bad['geometry'][field] = value; cases.append((field, bad))
        bad = copy.deepcopy(good); del bad['gs_passthrough_skip']; cases.append(('missing', bad))
        bad = copy.deepcopy(good); bad['geometry_version'] = 1; cases.append(('version', bad))
        raw = json.dumps(good)
        cases.append(('duplicate_root', raw[:-1] + ',"gs_passthrough_skip":' + json.dumps(original.skip_words([6])) + '}'))
        cases.append(('escaped_duplicate_root', raw[:-1] + ',"gs\\u005fpassthrough_skip":' + json.dumps(original.skip_words([6])) + '}'))
        bad = copy.deepcopy(good); bad['c0'] = [0, 0, 0, 0]; bad['c0_roots'] = [0] * 8; bad['c0_version'] = 2
        cases.append(('compute', bad))
        for name, reflection in cases:
            directory = args.out / ('reflection-' + name)
            iid = ('11' * 32); key = self.run_fixture('input-key', iid, cache=directory)['key']
            self.put_pair(directory, key, module, reflection)
            with self.subTest(case=name):
                self.assertFalse(self.load(directory, dict(key=key, iid=iid), 'loose')['accepted'])
        nested = copy.deepcopy(good); nested['metadata'] = dict(gs_passthrough_skip=original.skip_words([6]))
        directory = args.out / 'nested-metadata'; iid = '22' * 32
        key = self.run_fixture('input-key', iid, cache=directory)['key']
        self.put_pair(directory, key, module, nested)
        self.assertTrue(self.load(directory, dict(key=key, iid=iid), 'loose')['accepted'])
        vertex, reflection = self.module('vertex'); reflection['gs_passthrough_skip'] = original.skip_words([0])
        self.put_pair(directory, key, vertex, reflection)
        self.assertFalse(self.load(directory, dict(key=key, iid=iid), 'loose')['accepted'])
        bad = bytearray(module)
        words = list(struct.unpack('<' + 'I' * (len(bad) // 4), bad)); at = 5
        while at < len(words):
            length, op = words[at] >> 16, words[at] & 0xffff
            if op == 16 and words[at + 2] == 26:
                words[at + 3] = 1; break
            at += length
        self.put_pair(directory, key, struct.pack('<' + 'I' * len(words), *words), good)
        self.assertFalse(self.load(directory, dict(key=key, iid=iid), 'loose')['accepted'])
        position, reflection = self.module('pass_position')
        words = list(struct.unpack('<' + 'I' * (len(position) // 4), position)); at = 5
        while at < len(words):
            length, op = words[at] >> 16, words[at] & 0xffff
            if op == 22 and words[at + 2] == 32:
                words[at + 2] = 16
            at += length
        self.put_pair(directory, key, struct.pack('<' + 'I' * len(words), *words), reflection)
        self.assertFalse(self.load(directory, dict(key=key, iid=iid), 'loose')['accepted'])

    def test_bad_pack_cannot_hide_matching_loose_output_or_input(self):
        for bad_input in (False, True):
            directory, manifest, _, _ = self.seed('input' if bad_input else 'output')
            path = self.input_path(directory, manifest); owned = path.read_bytes()
            if bad_input:
                data = bytearray(owned); struct.pack_into('<I', data, 172 + 0x810, 2); path.write_bytes(data)
            else:
                self.put_pair(directory, manifest['key'], *self.module('pass_b'))
            self.packer.pack(directory, keep=True)
            path.write_bytes(owned)
            self.put_pair(directory, manifest['key'], *self.module('pass_a'))
            self.assertTrue(self.load(directory, manifest, 'private-packed')['accepted'])

    def test_record_reconstruction_retains_wire_format_and_rejects_native(self):
        directory, manifest, _, control = self.seed('record', record=True)
        answers = (directory / 'shader-answers.bin').read_bytes()
        programs = (directory / 'shader-programs.bin').read_bytes()
        self.assertEqual(struct.unpack_from('<II', answers, 8), (2, 217))
        self.assertEqual(programs[16 + 44:16 + 44 + 0x880], control.read_bytes())
        shutil.copyfile(directory / 'shader-answers.bin', directory / 'seed-answers.bin')
        shutil.copyfile(directory / 'shader-programs.bin', directory / 'seed-programs.bin')
        # Observe prepared entries alone, rather than retaining the original
        # met-in-play list which names the independently valid portable source.
        (directory / 'shader-answers.bin').unlink()
        valid = self.run_fixture('prepare', cache=directory)
        self.assertTrue(valid['accepted'])
        self.assertEqual(valid['failures'], 0)
        self.assertEqual(valid['entries'], [dict(iid=manifest['iid'], stage=3, priority=1)])
        data = bytearray(programs); struct.pack_into('<I', data, 16 + 44 + 0x810, 2)
        (directory / 'seed-programs.bin').write_bytes(data)
        rejected = self.run_fixture('prepare', cache=directory)
        # The command successfully writes an empty prepared file; its status
        # describes file publication, while failed shaders have no prepared IID.
        self.assertTrue(rejected['accepted'])
        self.assertEqual((rejected['failures'], rejected['entries']), (1, []))


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--cc', required=True)
    parser.add_argument('--opt', choices=('O0', 'O2'), default='O2')
    parser.add_argument('--source-revision')
    parser.add_argument('--translator', required=True)
    parser.add_argument('--spirv-val', required=True)
    parser.add_argument('--out', type=Path, required=True)
    parser.add_argument('--test', action='append', help='Run only this named test method; repeatable')
    args = parser.parse_args()
    suite = (unittest.TestSuite(PassthroughCache(name) for name in args.test) if args.test else
             unittest.defaultTestLoader.loadTestsFromTestCase(PassthroughCache))
    result = unittest.TextTestRunner(verbosity=2).run(suite)
    (args.out / 'result.json').write_text(json.dumps(dict(tests=result.testsRun, failures=len(result.failures),
        errors=len(result.errors), skipped=len(result.skipped)), indent=2) + '\n')
    raise SystemExit(not result.wasSuccessful())
